mapper.select:
SELECT 
    /* 1. 전체 항목 수 */
    (SELECT (SELECT COUNT(*) FROM TB_HOTDEAL_TRACKER) + (SELECT COUNT(*) FROM Common_Product) FROM DUAL) AS TOTALCOUNT,

    /* 2. 핫딜 상품 수 */
    (SELECT COUNT(*) FROM TB_HOTDEAL_TRACKER) AS HOTDEALCOUNT,

    /* 3. 일반 상품 수 */
    (SELECT COUNT(*) FROM Common_Product) AS NORMALCOUNT,

    /* 4. 핫딜 최종 동기화 시각 */
    (SELECT TO_CHAR(MAX(LAST_UPDATE_DATE), 'YYYY-MM-DD HH24:MI:SS') FROM TB_HOTDEAL_TRACKER) AS HOTDEALLASTSYNC,

    /* 5. 일반 상품 최종 동기화 시각 */
    (SELECT TO_CHAR(MAX(REG_DATE), 'YYYY-MM-DD HH24:MI:SS') FROM Common_Product) AS NORMALLASTSYNC,

    /* 6. 전체 최종 동기화 시각 (두 테이블의 MAX 중 더 큰 값) */
    (SELECT TO_CHAR(GREATEST(
        NVL((SELECT MAX(LAST_UPDATE_DATE) FROM TB_HOTDEAL_TRACKER), TO_DATE('1900-01-01', 'YYYY-MM-DD')),
        NVL((SELECT MAX(REG_DATE) FROM Common_Product), TO_DATE('1900-01-01', 'YYYY-MM-DD'))
    ), 'YYYY-MM-DD HH24:MI:SS') FROM DUAL) AS TOTALLASTSYNC
FROM DUAL
